// Author: MiYu. Minimal real-session checks for latent main, concurrent event data and trigger/timer continuation ownership.
#include "session.h"
#include "setup.h"
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=3)throw std::runtime_error("Usage: war3_session_thread_tests <data-root> <thread-fixture>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;auto session=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info);session->attachWorld(std::move(world));session->audioMuted(true);auto& vm=session->runtime();int leases=0,released=0;bool ownerLive=false;
        vm.bind("ThreadLease",[&](auto& runtime,auto args){++leases;struct Guard{int& leases;int& released;bool& ownerLive;ScriptSession* session;~Guard(){--leases;++released;ownerLive=session->units().size()==2;}}guard{leases,released,ownerLive,session.get()};runtime.invoke(args[0]);return runtime.nothing();});session->configure();PlayerSetup setup(info,session->config());session->applySetup(setup);unsigned passed=0;auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto value=[&](const char* name){return vm.global(name).bits;};
        session->startMain();require(session->mainStarted() && !session->mainCompleted() && value("main_before")==1 && value("main_after")==0,"Waiting main was reported complete");session->advance(.09375);require(!session->mainCompleted(),"Waiting main resumed early");session->advance(.03125);require(session->mainCompleted() && value("main_after")==1 && !vm.threadCount(),"Main continuation did not finish");++passed;std::cout<<"PASS waiting_main_and_completion_state\n";
        vm.start("Setup");session->selectUnit(value("first"),true);session->selectUnit(value("second"),true);require(value("event_done")==0 && vm.threadCount()==2 && vm.invoke("GetTriggerUnit").bits==0,"Event suspension contaminated host or failed to fork");session->advance(.125);require(value("event_done")==2 && !vm.threadCount() && vm.invoke("GetTriggeringTrigger").bits==0,"Concurrent event continuation lost context");++passed;std::cout<<"PASS independent_waiting_unit_events\n";
        vm.start("TimerBegin");session->advance(.0625);require(value("timer_done")==0 && vm.threadCount()==1,"Timer callback did not suspend independently");session->advance(.125);require(value("timer_done")==1 && !vm.threadCount() && vm.invoke("GetExpiredTimer").bits==0,"Timer continuation or caller context differs");++passed;std::cout<<"PASS sleeping_timer_callback_and_release\n";
        vm.start("RunSerial");require(value("serial_trace")==1 && value("execute_returned")==1,"TriggerExecute blocked its caller");session->advance(.125);require(value("serial_trace")==123,"Serial trigger actions crossed wait");vm.start("RunParallel");require(value("parallel_trace")==13,"Disabled wait-on-sleeps did not release next action");session->advance(.125);require(value("parallel_trace")==132,"Parallel action continuation did not return");vm.start("RunJoin");require(value("join_returned")==0 && vm.threadCount()==2,"TriggerExecuteWait did not hold caller");session->advance(.125);require(value("join_returned")==1 && value("serial_trace")==123 && !vm.threadCount(),"TriggerExecuteWait did not rejoin completed actions");++passed;std::cout<<"PASS trigger_serial_parallel_and_wait_join\n";
        vm.start("HoldLease");require(leases==1 && value("after_cancel")==0,"Session cancellation check did not retain native stack");session.reset();require(!leases && released==1 && ownerLive,"Session fields died before suspended native resources unwound");++passed;std::cout<<"PASS session_destruction_before_member_teardown\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed="<<passed<<" failed=0\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
